# (d)+(e) ACL proven in both directions with concurrent known traffic, and anonymous refusal. Runs in the guest, inside the
# broker container (mosquitto_pub/mosquitto_sub of the image; nothing to install on the host; no 'timeout' applet needed).
# Precondition, enforced by the next line: controller ready and 'drained' (no simulator/harness run may be in progress: the operator's rule).
T=$(date -u +%Y%m%dT%H%M%SZ); PR=stop; if wait_ready && drained && metrics itest-acl-$T before; then ssh egw-tcg "sh /opt/egw/deployment/scripts/probe-acl.sh $T"; PR=$?; echo "probe exit=$PR (0 PASS, 1 FAIL, 3 INCONCLUSIVE, 2 usage/precondition: nothing was run and there is no verdict.txt, 255 ssh failed: nothing is known; about 100 s)"; metrics itest-acl-$T after; [ "$PR" = 0 ] || stop "test 9(d): probe exit=$PR - NOT a pass (1 FAIL, 3 INCONCLUSIVE, anything else: the probe did not run to its end)"; else stop "test 9(d): precondition failed - the probe was NOT run"; fi
[ "${PR:-stop}" != stop ] && scp -r egw-tcg:/opt/egw/evidence/itest-acl-$T ~/egw-tcg/itest/ || stop "test 9(d): probe not run (PR='$PR') or scp failed - no evidence was copied"
B=~/egw-tcg/itest/itest-acl-$T.metrics.before.json; A=~/egw-tcg/itest/itest-acl-$T.metrics.after.json; if [ "${PR:-stop}" != stop ] && [ -s $B ] && [ -s $A ] && [ -s ~/egw-tcg/itest/itest-acl-$T/verdict.txt ]; then python3 -c 'import json,sys; b,a=(json.load(open(p)) for p in sys.argv[1:3]); d=[k for k in ("started_at","accepted","rejected","duplicate","failed","dropped") if a[k]!=b[k]]; print("changed fields:", d); sys.exit(1 if d else 0)' $B $A && echo "controller untouched by the probe" || stop "test 9(d): controller counters or started_at changed during the probe, or a snapshot is not valid /metrics JSON"; else stop "test 9(d): probe not run (PR='$PR'), or a metrics snapshot or verdict.txt is missing or empty - NOTHING was compared"; fi
[ "${PR:-stop}" != stop ] && { cat ~/egw-tcg/itest/itest-acl-$T/verdict.txt ~/egw-tcg/itest/itest-acl-$T/ctl-sub.out && wc -c ~/egw-tcg/itest/itest-acl-$T/sim-sub.out ~/egw-tcg/itest/itest-acl-$T/anon.out && cat ~/egw-tcg/itest/itest-acl-$T/broker.txt; } || stop "test 9(d): nothing to show (PR='$PR') or an evidence file is missing"
